295: static int rds_rdma_init(void)
296: {
297: 	int ret;
298: 
299: 	ret = rds_ib_init();
300: 	if (ret)
301: 		goto out;
302: 
303: 	ret = rds_rdma_listen_init();
304: 	if (ret)
305: 		rds_ib_exit();
306: out:
307: 	return ret;
308: }
309: module_init(rds_rdma_init);
310: 
311: static void rds_rdma_exit(void)
312: {
313: 	/* stop listening first to ensure no new connections are attempted */
314: 	rds_rdma_listen_stop();
315: 	rds_ib_exit();
316: }
